class Solution {
public:
    int maxNumOfMarkedIndices(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int lo = 0, hi = n / 2, ans = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            bool ok = true;
            for (int i = 0; i < mid; i++) {
                if (2 * nums[i] > nums[n - mid + i]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans * 2;
    }
};
